<section class="panel repository-intro"><div class="panel-head"><div><span class="section-kicker">LEVELENGINE · <?=e(le_text('ROZSZERZ MOŻLIWOŚCI'))?></span><h2>Marketplace</h2><p><?=e(le_text('Motywy i pluginy z oficjalnego repozytorium LevelStudio.'))?></p></div><span class="status <?=$online?'ok':'draft'?>"><?=e(le_text(['remote'=>'Połączono','cached'=>'Zapisany katalog','stale'=>'Katalog archiwalny','fallback'=>'Katalog lokalny'][$source]))?></span></div><div class="repository-details"><span>cms.levelgame.pl <span>· HTTPS · SHA-256</span></span><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="repository_refresh"><button class="btn" type="submit">↻ <?=e(le_text('Odśwież połączenie'))?></button></form></div><?php if($catalog['fetched_at']):?><p class="workspace-note"><?=e(le_text('Ostatnie pobranie:'))?> <?=e(date('d.m.Y H:i',$catalog['fetched_at']))?> · <?=e(le_text('Instalacja zawsze ponownie sprawdza katalog online.'))?></p><?php endif;?><?php if($catalog['error']):?><div class="repository-warning" role="status"><b><?=e(le_text('Repozytorium jest chwilowo niedostępne'))?></b><p><?=e(le_text($catalog['error']))?></p><small><?=e(le_text('Możesz przeglądać dostępny katalog. Instalacja z repozytorium wymaga połączenia. Zaufane paczki ZIP można wgrać w Pluginach lub Motywach.'))?></small></div><?php endif;?></section>
